window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[165]={"id":"165","numero":165,"titre":"Oreillons","objectifs":[{"id":"165-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des oreillons","contenu":"<div class=\"notion-course\"><p><span>Les</span> <strong><span>oreillons</span></strong> sont une <strong>infection <span>virale</span> aiguë</strong>,\n      <strong>contagieuse</strong> et <strong>le plus souvent bénigne</strong>, due au <span>virus ourlien</span>\n      — un virus à <span><span class=\"nc-purple_bg nc-bold\">ARN</span></span> de la famille des <strong><span><span class=\"nc-purple_bg nc-bold\">Paramyxoviridae</span></span></strong>.</p>\n      <table>\n        <thead><tr><th>Item</th><th>Caractéristique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Agent</strong></td><td><span>Virus ourlien</span>, virus à <span><span class=\"nc-purple_bg nc-bold\">ARN</span></span>, famille des <span><span class=\"nc-purple_bg nc-bold\">Paramyxoviridae</span></span></td></tr>\n          <tr><td><strong>Réservoir</strong></td><td><span>Strictement humain</span></td></tr>\n          <tr><td><strong><span>Épidémiologie</span></strong></td><td><span class=\"nc-yellow_bg\">Infection </span><span><span class=\"nc-yellow_bg\">endémique</span></span><span class=\"nc-yellow_bg\"> dans le monde</span> ; devenue <strong><span class=\"nc-green_bg\">rare en France</span></strong> <span class=\"nc-green_bg\">grâce au </span><span><span class=\"nc-green_bg\">ROR</span></span> (couverture vaccinale <span>&gt; 95 %</span> dans <span>les</span> pays industrialisés) ; <strong><span>non éradiquée</span></strong> — couverture encore insuffisante</td></tr>\n          <tr><td><strong><span>Terrain</span></strong></td><td><span class=\"nc-pink_bg\">Majorité des cas chez l'</span><strong><span class=\"nc-pink_bg\">enfant</span></strong> (collectivités, écoles) ; <strong>survenue tardive de plus en plus fréquente</strong> (<span class=\"nc-red nc-bold\">augmentation de la fréquence </span><span><span class=\"nc-red nc-bold\">après la puberté</span></span>)</td></tr>\n          <tr><td><strong>Immunité</strong></td><td><strong>Durable, à vie</strong> après la maladie ; <span class=\"nc-green_bg\">protection vaccinale efficace</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">L’immunité est habituellement durable, mais une réinfection est possible. Une nouvelle parotidite fait rechercher d’autres causes sans exclure automatiquement les oreillons.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-165.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 165</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/sante/themes/oreillons/mesures-hygiene-vaccination\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · oreillons et éviction de collectivité</a></li></ul></details>","frequence":0},{"id":"165-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le tropisme du virus des oreillons et les modalités de transmission","contenu":"<div class=\"notion-course\"><p>Le virus ourlien présente un <strong>double tropisme</strong> : <span><span class=\"nc-purple_bg\">glandulaire</span></span> et <span><span class=\"nc-purple_bg\">neurologique</span></span>.</p>\n      <table>\n        <thead><tr><th>Tropisme</th><th>Atteintes</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"nc-purple_bg\">Glandulaire</span></strong></td><td><span>Parotidite</span> ; <span>orchite</span> ; <span>pancréatite</span></td></tr>\n          <tr><td><strong><span class=\"nc-purple_bg\">Neurologique</span></strong></td><td><span>Méningite</span> ; <span>encéphalite</span> (rarement)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Transmission</strong> interhumaine <strong>directe</strong>, par la salive :</p>\n      <ul>\n        <li><strong><span class=\"nc-red nc-bold\">Inhalation de </span><span><span class=\"nc-red nc-bold\">gouttelettes</span></span><span class=\"nc-red nc-bold\"> de salive</span></strong> émises par un sujet malade</li>\n        <li><strong><span>Contact</span> direct avec la salive</strong> d'un sujet malade</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Contagiosité.</strong> Le sujet est contagieux <strong><span><span class=\"nc-pink_bg\">2 jours avant</span></span></strong><span class=\"nc-pink_bg\"> </span><span><span class=\"nc-pink_bg\">les</span></span><span class=\"nc-pink_bg\"> premiers symptômes</span>\n        et <strong><span><span class=\"nc-pink_bg\">4 jours après</span></span></strong> — d'où une <span>diffusion</span> possible <strong><span>avant tout signe clinique</span></strong>.\n      </div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-165.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 165</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/sante/themes/oreillons/mesures-hygiene-vaccination\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · oreillons et éviction de collectivité</a></li></ul></details>","frequence":1},{"id":"165-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic des oreillons","contenu":"<div class=\"notion-course\"><p>Le diagnostic des oreillons est <strong>clinique</strong> dans la forme typique — il repose sur un\n      <span>contexte évocateur</span> et le tableau de <span>parotidite</span>.\n      <span>Les</span> examens complémentaires ne sont utiles qu'en cas de doute ou de complication.</p>\n      <p><strong>Contexte évocateur :</strong> <span>contage récent</span>,\n      <span>absence ou incomplétude de vaccination</span>, épidémie en saison hivernale.</p>\n      <p><strong>Incubation longue :</strong> environ <strong><span><span class=\"nc-pink_bg nc-bold\">3 semaines</span></span></strong>\n      (<span><span class=\"nc-pink nc-bold\">15 à 25 jours</span></span>, en moyenne <span>19 jours</span>).</p>\n      <p>L'infection est <strong><span class=\"nc-green nc-bold\">asymptomatique</span> dans <span>1/3</span> des cas</strong>. Sinon, l'<span>évolution</span> se fait en deux phases :</p>\n      <table>\n        <thead><tr><th>Phase</th><th>Durée</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Invasion</strong></td><td><span><span class=\"nc-pink nc-bold\">24-48 h</span></span></td><td><span>Fièvre modérée</span> ; <span>malaise</span> ; <span><span class=\"nc-blue_bg\">gêne à la mastication</span></span> ; <span><span class=\"nc-blue_bg\">otalgie</span></span></td></tr>\n          <tr><td><strong>État</strong></td><td>≈ <span><span class=\"nc-pink nc-bold\">1 semaine</span></span></td><td><span>Parotidite ourlienne</span> — <span class=\"nc-red_bg\">présente dans </span><span><span class=\"nc-red_bg\">70 %</span></span><span class=\"nc-red_bg\"> des cas</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Parotidite ourlienne — sémiologie :</strong></p>\n      <ul>\n        <li><span class=\"nc-yellow_bg\">Parotide </span><span><span class=\"nc-yellow_bg\">tuméfiée et douloureuse</span></span>, refoulant le <strong>lobe de l'oreille en haut et en dehors</strong> et comblant le <strong>sillon rétromaxillaire</strong></li>\n        <li><span class=\"nc-yellow_bg\">Visage en forme de poire</span> — <strong><span><span class=\"nc-yellow_bg\">faciès piriforme</span></span></strong></li>\n        <li>Atteinte <strong><span class=\"nc-yellow_bg\">unilatérale puis</span> <span class=\"nc-yellow_bg\">bilatérale</span></strong> (bilatéralisation simultanée possible, mais le plus <span class=\"nc-pink nc-bold\">souvent décalée de quelques jours</span>)</li>\n        <li>Turgescence et rougeur de l'ostium du <strong><span class=\"nc-blue_bg nc-bold\">canal de Sténon</span></strong> (canal parotidien)</li>\n        <li><span><span class=\"nc-orange_bg\">Adénopathies</span></span><span class=\"nc-orange_bg\"> prétragiennes et sous-angulo-maxillaires</span></li>\n        <li>Signes associés possibles : <span><span class=\"nc-blue_bg\">céphalées</span></span>, <span><span class=\"nc-orange_bg\">pharyngite</span></span>, <span class=\"nc-orange_bg\">atteinte des glandes salivaires accessoires</span>, <span>sécheresse buccale</span></li>\n      </ul>\n      <p><span>Les</span> <span class=\"nc-green_bg\">signes généraux</span> sont <strong><span class=\"nc-green_bg\">peu marqués chez l'enfant</span></strong>, mais <strong><span class=\"nc-red_bg\">marqués chez l'adolescent et l'adulte</span></strong>.</p>\n      <div class=\"callout callout-danger\">\n        <strong>Discriminant — pas d'écoulement.</strong> Dans la <span class=\"nc-red nc-bold\">parotidite ourlienne</span>, il n'y a\n        <strong><span>pas d'écoulement de pus</span></strong> à l'ostium du <span class=\"nc-blue_bg nc-bold\">canal de Sténon</span> : un écoulement\n        purulent oriente vers une <strong>parotidite <span>bactérienne</span></strong>, pas vers <span>les</span> oreillons.\n      </div>\n      <div class=\"callout callout-warn\">L’immunité est habituellement durable, mais une réinfection est possible. Une nouvelle parotidite fait rechercher d’autres causes sans exclure automatiquement les oreillons.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 90 — Pathologie des glandes salivaires</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-165.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 165</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/sante/themes/oreillons/mesures-hygiene-vaccination\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · oreillons et éviction de collectivité</a></li></ul></details>","frequence":0},{"id":"165-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités évolutives des oreillons","contenu":"<div class=\"notion-course\"><p>Dans la <strong>majorité des cas</strong>, <span>les</span> oreillons évoluent vers une\n      <strong><span class=\"nc-green_bg\">guérison</span> <span class=\"nc-green_bg nc-bold\">spontanée</span> en <span>8 à 10 jours</span></strong>, en dehors de certaines complications.</p>\n      <table>\n        <thead><tr><th>Atteinte</th><th><span>Évolution</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Parotidite</strong></td><td><span class=\"nc-green_bg\">Guérison</span> <strong><span class=\"nc-green_bg nc-bold\">spontanée</span></strong> en <span>8-10 jours</span></td></tr>\n          <tr><td><strong><span>Orchite</span></strong></td><td><span>Évolution</span> favorable en <span>1 à 2 semaines</span></td></tr>\n          <tr><td><strong><span>Pancréatite</span></strong></td><td><strong><span class=\"nc-green nc-bold\">Guérison sans séquelle</span></strong></td></tr>\n          <tr><td><strong><span>Méningite</span></strong></td><td><strong><span class=\"nc-green nc-bold\">Guérison sans séquelle</span></strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège — complication locale.</strong> Au décours de la parotidite, des <strong><span><span class=\"nc-orange_bg\">foyers de nécrose</span></span></strong><span class=\"nc-orange_bg\">\n        peuvent apparaître</span> et faire le lit d'une <strong><span><span class=\"nc-red nc-bold\">parotidite chronique</span></span></strong>.\n      </div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-165.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 165</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/sante/themes/oreillons/mesures-hygiene-vaccination\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · oreillons et éviction de collectivité</a></li></ul></details>","frequence":1},{"id":"165-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des complications des oreillons","contenu":"<div class=\"notion-course\"><p><span>Les</span> complications des oreillons relèvent du <strong>double tropisme</strong> du virus :\n      atteintes <strong>glandulaires</strong> et atteintes <strong>extra-glandulaires (neurologiques)</strong>.</p>\n      <p><strong>Atteintes glandulaires :</strong></p>\n      <table>\n        <thead><tr><th>Atteinte</th><th>Fréquence</th><th>Signes cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Parotidite</strong></td><td><span>70 %</span></td><td>Manifestation typique (cf. rubrique <em><span>Diagnostic positif</span></em>)</td></tr>\n          <tr><td><strong><span>Orchite</span> / épididymite</strong></td><td><span>35 %</span></td><td>\n            <strong><span>Terrain</span> :</strong> <span class=\"nc-pink nc-bold\">sujet </span><strong><span class=\"nc-pink nc-bold\">pubère</span></strong> ou <span class=\"nc-pink nc-bold\">adulte jeune</span> (après la puberté)<br>\n            <strong>Délai :</strong> apparaît <span>4 à 8 jours après</span> la parotidite<br>\n            <strong>Latéralité :</strong> <span>unilatérale</span> le plus souvent<br>\n            <strong>Clinique :</strong> <span class=\"nc-red_bg\">recrudescence fébrile</span> ; <span><span class=\"nc-blue_bg\">douleurs testiculaires à irradiation abdominale</span></span> ; <span><span class=\"nc-blue_bg\">tuméfaction très douloureuse du testicule</span></span> ; <span class=\"nc-yellow_bg\">réaction </span><span><span class=\"nc-yellow_bg\">inflammatoire</span></span><span class=\"nc-yellow_bg\"> de la vaginale</span>, du scrotum, voire du cordon spermatique\n          </td></tr>\n          <tr><td><strong><span>Pancréatite</span></strong></td><td><span>4 %</span></td><td><strong><span class=\"nc-green nc-bold\">Asymptomatique le plus souvent</span></strong> (ou peu sévère) ; <span>œdémateuse à l'imagerie</span> ; <span class=\"nc-green nc-bold\">guérison sans séquelle</span></td></tr>\n          <tr><td><strong><span class=\"nc-orange_bg\">Ovarite</span>, <span class=\"nc-orange_bg\">mastite</span></strong></td><td>Exceptionnelles</td><td>Possibles <span class=\"nc-pink nc-bold\">en période </span><strong><span class=\"nc-pink nc-bold\">post-pubertaire</span></strong></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Atteintes extra-glandulaires (neurologiques) :</strong></p>\n      <table>\n        <thead><tr><th>Atteinte</th><th>Fréquence</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span><span class=\"nc-orange_bg\">Méningite</span></span><span class=\"nc-orange_bg\"> lymphocytaire</span></strong></td><td>Fréquente ++</td><td>Souvent <strong>infra-clinique</strong> ; associée dans <span>50 %</span> des cas à une atteinte <span class=\"nc-purple_bg\">glandulaire</span> ; <strong><span class=\"nc-green nc-bold\">guérison sans séquelle</span></strong></td></tr>\n          <tr><td><strong><span><span class=\"nc-orange_bg\">Encéphalite</span></span></strong></td><td>Rare (<span>1 %</span>)</td><td><strong><span>Décès dans 1-5 % des cas</span></strong> ; atteinte spécifique du <strong>contingent auditif du nerf VIII</strong> → <strong><span class=\"nc-red nc-bold\">surdité</span> possible, parfois définitive</strong></td></tr>\n          <tr><td><strong><span class=\"nc-orange_bg\">Myélite</span>, <span class=\"nc-orange_bg\">polyradiculonévrite aiguë</span></strong></td><td>Possibles</td><td>Atteintes neurologiques plus rares</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Complication grave — <span><span class=\"nc-orange_bg\">encéphalite</span></span> ourlienne.</strong> Rare (<span>1 %</span>) mais sévère :\n        <strong><span>létalité 1-5 %</span></strong> et atteinte <strong>spécifique du contingent auditif du nerf VIII</strong>,\n        responsable d'une <strong><span class=\"nc-red nc-bold\">surdité</span> parfois définitive</strong>. C'est le pivot QCM de l'item.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir — orchite.</strong> L'orchite ourlienne touche le <strong><span class=\"nc-pink nc-bold\">sujet pubère</span></strong>, survient\n        <span><span class=\"nc-pink nc-bold\">4-8 jours après</span></span><span class=\"nc-pink nc-bold\"> la parotidite</span> et expose à une\n        <strong><span><span class=\"nc-red_bg\">atrophie testiculaire séquellaire dans</span> 50 % des <span class=\"nc-red_bg\">cas</span></span></strong> — mais la\n        <strong>stérilité reste rare</strong>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span>Méningite</span> - <span>méningoencéphalite</span> · 89 — Altération fonction auditive · 50 — Pathologie génito-scrotale chez le garçon et chez l'homme · 358 — <span>Pancréatite aiguë</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-165.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 165</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/sante/themes/oreillons/mesures-hygiene-vaccination\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · oreillons et éviction de collectivité</a></li></ul></details>","frequence":2},{"id":"165-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens complémentaires en cas de suspicion d’oreillons","contenu":"<div class=\"notion-course\"><p>Dans la <strong>forme typique</strong> (parotidite dans un <span>contexte évocateur</span>), le diagnostic est <strong>clinique</strong> :\n      <strong><span>aucun examen complémentaire n'est nécessaire</span></strong>.</p>\n      <p><span>Les</span> examens complémentaires ne sont indiqués que dans <strong>deux situations</strong> :</p>\n      <ul>\n        <li>En cas de <strong><span><span class=\"nc-purple_bg\">doute diagnostique</span></span></strong></li>\n        <li>En cas de <strong>complication</strong>, en particulier une <strong>localisation <span>extra-parotidienne</span> isolée</strong>\n        (<span>orchite</span>, <span>méningite</span> ou <span>pancréatite</span> sans parotidite associée)</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Devant une parotidite typique de l'enfant en contexte épidémique, on ne demande\n        <strong>rien</strong>. <span>Les</span> examens ne servent qu'à trancher un doute ou à documenter une forme <span>extra-parotidienne</span> isolée.\n      </div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-165.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 165</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/sante/themes/oreillons/mesures-hygiene-vaccination\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · oreillons et éviction de collectivité</a></li></ul></details>","frequence":1},{"id":"165-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de confirmation des oreillons","contenu":"<div class=\"notion-course\"><ul><li>La confirmation virologique repose surtout sur RT-PCR d’un prélèvement salivaire/buccal précoce, selon protocole du laboratoire ; elle est utile devant doute, complication ou investigation de cas groupés.</li><li>Une PCR négative tardive n’exclut pas la maladie. Chez le vacciné, IgM peuvent manquer et IgG anciennes ne prouvent pas un épisode aigu ; interprétation sérologique avec contexte et laboratoire.</li><li>Biologie non spécifique selon complication : lipase si pancréatite suspectée, <span class=\"nc-red nc-bold\">LCS</span> si syndrome méningé et indication. Une hyperamylasémie peut être salivaire et ne suffit pas au diagnostic de pancréatite.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-165.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 165</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/sante/themes/oreillons/mesures-hygiene-vaccination\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · oreillons et éviction de collectivité</a></li></ul></details>","frequence":0},{"id":"165-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités thérapeutique des oreillons","contenu":"<div class=\"notion-course\"><ul><li>Traitement symptomatique : hydratation, antalgiques adaptés, <span class=\"nc-green_bg\">repos</span> ; soutien scrotal si orchite. Une douleur testiculaire aiguë impose d’exclure une torsion.</li><li>Pas d’antiviral spécifique. Mesures d’hygiène respiratoire et limitation des contacts pendant la phase contagieuse ; éviter la collectivité en phase aiguë.</li><li>Distinguer l’absence d’éviction scolaire réglementaire systématique d’une absence de précautions. Informer et vérifier la vaccination de l’entourage ; en cas de cas groupés, suivre l’ARS.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-165.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 165</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/sante/themes/oreillons/mesures-hygiene-vaccination\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · oreillons et éviction de collectivité</a></li></ul></details>","frequence":1},{"id":"165-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les moyens préventifs des oreillons","contenu":"<div class=\"notion-course\"><p>La vaccination est la prévention spécifique des oreillons ; elle s’associe aux mesures d’hygiène et à l’éviction pendant la période recommandée.</p>\n      <ul>\n        <li>Vaccin <strong><span>ROR</span></strong> (<span>Rougeole</span> - Oreillons - <span>Rubéole</span>)</li>\n        <li><strong>Il n'existe pas de vaccin <span>monovalent</span></strong> contre <span>les</span> oreillons en France</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Prévention = <strong><span>ROR</span></strong>, pas de vaccin oreillons isolé.\n        La couverture vaccinale française reste <strong><span>insuffisante pour l'éradication</span></strong> :\n        la maladie est devenue rare mais persiste.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span>Vaccination</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-165.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 165</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/sante/themes/oreillons/mesures-hygiene-vaccination\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · oreillons et éviction de collectivité</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"principes":"<p>Repères de conduite à tenir, reliés aux objectifs détaillés :</p><ul><li><strong>Connaître les modalités du diagnostic des oreillons</strong> — Le diagnostic des oreillons est clinique dans la forme typique — il repose sur un\n      contexte évocateur et le tableau de parotidite.\n      Les examens complémentaires ne sont utiles qu&#x27;en cas de doute ou de complication.\n      Contexte évocateur : contage récent,\n      absence ou incomplétude de vaccination, épidémie en saison hivernale.\n      Incubation longue : environ 3 semaines\n      (15 à 25 jours, en moyenne 19 jours).\n      L&#x27;infection est asymptomatique dans 1/3 des cas.</li><li><strong>Connaître les modalités évolutives des oreillons</strong> — Dans la majorité des cas, les oreillons évoluent vers une\n      guérison spontanée en 8 à 10 jours, en dehors de certaines complications.\n      \n        AtteinteÉvolution\n        \n          ParotiditeGuérison spontanée en 8-10 jours\n          OrchiteÉvolution favorable en 1 à 2 semaines\n          PancréatiteGuérison sans séquelle\n          MéningiteGuérison sans séquelle\n        \n      \n      \n        Piège — complication locale.</li><li><strong>Connaître les signes cliniques des complications des oreillons</strong> — Les complications des oreillons relèvent du double tropisme du virus :\n      atteintes glandulaires et atteintes extra-glandulaires (neurologiques).\n      Atteintes glandulaires :\n      \n        AtteinteFréquenceSignes cliniques\n        \n          Parotidite70 %Manifestation typique (cf.</li><li><strong>Connaître les modalités thérapeutique des oreillons</strong> — Traitement symptomatique : hydratation, antalgiques adaptés, repos ; soutien scrotal si orchite.</li><li><strong>Connaître les moyens préventifs des oreillons</strong> — La vaccination est la prévention spécifique des oreillons ; elle s’associe aux mesures d’hygiène et à l’éviction pendant la période recommandée.\n      \n        Vaccin ROR (Rougeole - Oreillons - Rubéole)\n        Il n&#x27;existe pas de vaccin monovalent contre les oreillons en France\n      \n      \n        À retenir.</li></ul>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-165.pdf","label":"Collège Pilly — Oreillons (item 165, PDF)"}],"cards":[{"i":"42117d388565","n":165,"o":"165-1","u":"Définition","t":"Connaître la définition des oreillons","q":"Quel est l'agent causal spécifique des oreillons et ses caractéristiques virologiques ?","a":"<div class=\"notion-course\"><p>L'agent causal des oreillons est le <strong>virus ourlien</strong>, qui est un <strong>virus à <span class=\"nc-purple_bg nc-bold\">ARN</span></strong> appartenant à la famille des <strong><span class=\"nc-purple_bg nc-bold\">Paramyxoviridae</span></strong>.</p></div>"},{"i":"52161b26f0bb","n":165,"o":"165-1","u":"Définition","t":"Connaître la définition des oreillons","q":"Qu'est-ce que la définition médicale des oreillons ?","a":"<div class=\"notion-course\"><p>Les oreillons sont une <strong>infection virale aiguë</strong>, <strong>contagieuse</strong> et le plus souvent <strong>bénigne</strong>, provoquée par le <strong>virus ourlien</strong>.</p></div>"},{"i":"8b25955ba3aa","n":165,"o":"165-1","u":"Définition","t":"Connaître la définition des oreillons","q":"Quel est le réservoir et le principal terrain d'infection pour les oreillons ?","a":"<div class=\"notion-course\"><p>Le réservoir du virus ourlien est <strong>strictement humain</strong>. La majorité des cas survient chez l'<strong>enfant</strong>, notamment en collectivités, bien que l'on observe une survenue de plus en plus fréquente de cas après la puberté.</p></div>"},{"i":"5358e94f6d67","n":165,"o":"165-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des oreillons","q":"Quel est le signe clinique permettant de différencier une parotidite ourlienne d'une parotidite bactérienne ?","a":"<div class=\"notion-course\"><p>Le signe discriminant est l'<strong>absence d'écoulement purulent</strong> à l'ostium du <span class=\"nc-blue_bg nc-bold\">canal de Sténon</span> dans la parotidite ourlienne. Un écoulement purulent oriente vers une <strong>parotidite bactérienne</strong>.</p></div>"},{"i":"66915cdb8e8f","n":165,"o":"165-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des oreillons","q":"Quel élément clinique écarte le diagnostic d'oreillons et doit faire évoquer une autre pathologie ?","a":"<div class=\"notion-course\"><p>L’immunité est habituellement durable, mais une réinfection est possible. Une nouvelle parotidite fait rechercher d’autres causes sans exclure automatiquement les oreillons.</p></div>"},{"i":"b3adefe35919","n":165,"o":"165-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des oreillons","q":"Dans quel cas le diagnostic d'oreillons est-il clinique ?","a":"<div class=\"notion-course\"><p>Le diagnostic des oreillons est clinique dans les <strong>formes typiques</strong>. Il repose sur un <strong>contexte épidémiologique évocateur</strong> (contage, absence de vaccination, épidémie hivernale) et la présence d'une <strong>parotidite</strong>.</p></div>"},{"i":"be35e9effc48","n":165,"o":"165-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des oreillons","q":"Comment se manifeste une parotidite ourlienne typique au cours des oreillons ?","a":"<div class=\"notion-course\"><p>Une parotidite ourlienne se caractérise par :</p><ul><li>Une <strong><span class=\"nc-yellow_bg\">parotide tuméfiée et douloureuse</span></strong>, refoulant le lobe de l'oreille en haut et en dehors et comblant le sillon rétromaxillaire, donnant un « <strong><span class=\"nc-yellow_bg\">faciès piriforme</span></strong> » (en poire).</li><li>Une atteinte initialement <strong>unilatérale</strong>, puis souvent <span class=\"nc-yellow_bg\">bilatérale</span> (décalée de quelques jours).</li><li>Une <strong>turgescence et rougeur de l'ostium du <span class=\"nc-blue_bg nc-bold\">canal de Sténon</span></strong> (sans écoulement purulent).</li><li>Des <strong><span class=\"nc-orange_bg\">adénopathies prétragiennes</span></strong><span class=\"nc-orange_bg\"> et sous-angulo-maxillaires</span> associées.</li></ul></div>"},{"i":"1dda85eee836","n":165,"o":"165-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des complications des oreillons","q":"Quels sont les signes cliniques de l'orchite/épididymite ourlienne ?","a":"<div class=\"notion-course\"><p>L'orchite/épididymite ourlienne survient typiquement chez le <span class=\"nc-pink nc-bold\">sujet </span><strong><span class=\"nc-pink nc-bold\">pubère</span> ou <span class=\"nc-pink nc-bold\">adulte jeune</span></strong>, <strong>4 à 8 jours après la parotidite</strong>. Les signes cliniques incluent :</p><ul><li><span class=\"nc-red_bg\">Recrudescence fébrile</span></li><li><span class=\"nc-blue_bg\">Douleurs testiculaires à irradiation abdominale</span></li><li><span class=\"nc-blue_bg\">Tuméfaction très douloureuse du testicule</span></li><li><span class=\"nc-yellow_bg\">Réaction inflammatoire de la vaginale</span>, du scrotum, et parfois du cordon spermatique</li></ul><p>Elle est le plus souvent <strong>unilatérale</strong> et expose à une <span class=\"nc-red_bg\">atrophie testiculaire séquellaire dans</span> 50 % des <span class=\"nc-red_bg\">cas</span>, mais la stérilité est rare.</p></div>"},{"i":"33b0bbb8b69f","n":165,"o":"165-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des complications des oreillons","q":"Quels sont les signes cliniques de la méningite lymphocytaire ourlienne ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-orange_bg\">méningite lymphocytaire</span> ourlienne est <strong>fréquente</strong>, souvent <strong>infra-clinique</strong>, et associée dans 50 % des cas à une atteinte <span class=\"nc-purple_bg\">glandulaire</span>. Elle se caractérise par une <span class=\"nc-green nc-bold\">guérison sans séquelle</span>.</p></div>"},{"i":"93efc466c107","n":165,"o":"165-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des complications des oreillons","q":"Quelle est la particularité clinique de la pancréatite ourlienne ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-orange_bg\">pancréatite ourlienne</span>, qui survient dans <strong>4 %</strong> des cas, est le plus souvent <strong><span class=\"nc-green nc-bold\">asymptomatique</span></strong> ou peu sévère. Elle est de type œdémateuse à l'imagerie et guérit spontanément sans séquelle.</p></div>"},{"i":"c88dfd341470","n":165,"o":"165-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des complications des oreillons","q":"Quels sont les signes cliniques de l'encéphalite ourlienne ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-orange_bg\">encéphalite</span> ourlienne est une complication <strong>rare (1 %) mais sévère</strong>. Elle est associée à une <strong>létalité de 1 à 5 %</strong> et se caractérise par une atteinte spécifique du <strong>contingent auditif du nerf VIII</strong>, responsable d'une <strong><span class=\"nc-red nc-bold\">surdité</span> parfois définitive</strong>.</p></div>"},{"i":"d7ffa4fbc2e1","n":165,"o":"165-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des complications des oreillons","q":"Quels sont les signes cliniques des autres atteintes neurologiques rares des oreillons ?","a":"<div class=\"notion-course\"><p>Outre la méningite et l'<span class=\"nc-orange_bg\">encéphalite</span>, des atteintes neurologiques plus rares telles que la <strong><span class=\"nc-orange_bg\">myélite</span></strong> et la <strong><span class=\"nc-orange_bg\">polyradiculonévrite aiguë</span></strong> sont possibles lors des oreillons.</p></div>"},{"i":"4c05faa7c9ac","n":165,"o":"165-9","u":"Prise en charge","t":"Connaître les moyens préventifs des oreillons","q":"Quel est le moyen préventif unique des oreillons en France ?","a":"<div class=\"notion-course\"><p>Le seul moyen préventif des oreillons en France est la <strong>vaccination</strong>.</p></div>"},{"i":"a71918b921ca","n":165,"o":"165-9","u":"Prise en charge","t":"Connaître les moyens préventifs des oreillons","q":"Quel est le vaccin utilisé en France pour la prévention des oreillons ?","a":"<div class=\"notion-course\"><p>Le vaccin utilisé en France pour la prévention des oreillons est le <strong>vaccin trivalent ROR</strong> (Rougeole-Oreillons-Rubéole).</p></div>"},{"i":"b9786b20ccf4","n":165,"o":"165-9","u":"Prise en charge","t":"Connaître les moyens préventifs des oreillons","q":"Existe-t-il un vaccin monovalent contre les oreillons en France ?","a":"<div class=\"notion-course\"><p>Non, il n'existe <strong>pas de vaccin monovalent</strong> (vaccin isolé) contre les oreillons en France.</p></div>"},{"i":"32b7c98a5e2c","n":165,"o":"165-2","u":"Physiopathologie","t":"Connaître le tropisme du virus des oreillons et les modalités de transmission","q":"Quels sont les points essentiels concernant le tropisme du virus des oreillons et les modalités de transmission ?","a":"<div class=\"notion-course\"><p>Le virus ourlien présente un <strong>double tropisme</strong> : <span><span class=\"nc-purple_bg\">glandulaire</span></span> et <span><span class=\"nc-purple_bg\">neurologique</span></span>.</p>\n      <table>\n        <thead><tr><th>Tropisme</th><th>Atteintes</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"nc-purple_bg\">Glandulaire</span></strong></td><td><span>Parotidite</span> ; <span>orchite</span> ; <span>pancréatite</span></td></tr>\n          <tr><td><strong><span class=\"nc-purple_bg\">Neurologique</span></strong></td><td><span>Méningite</span> ; <span>encéphalite</span> (rarement)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Transmission</strong> interhumaine <strong>directe</strong>, par la salive :</p>\n      <ul>\n        <li><strong><span class=\"nc-red nc-bold\">Inhalation de </span><span><span class=\"nc-red nc-bold\">gouttelettes</span></span><span class=\"nc-red nc-bold\"> de salive</span></strong> émises par un sujet malade</li>\n        <li><strong><span>Contact</span> direct avec la salive</strong> d'un sujet malade</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Contagiosité.</strong> Le sujet est contagieux <strong><span><span class=\"nc-pink_bg\">2 jours avant</span></span></strong><span class=\"nc-pink_bg\"> </span><span><span class=\"nc-pink_bg\">les</span></span><span class=\"nc-pink_bg\"> premiers symptômes</span>\n        et <strong><span><span class=\"nc-pink_bg\">4 jours après</span></span></strong> — d'où une <span>diffusion</span> possible <strong><span>avant tout signe clinique</span></strong>.\n      </div></div>"},{"i":"a7f46a209649","n":165,"o":"165-4","u":"Diagnostic positif","t":"Connaître les modalités évolutives des oreillons","q":"Quels sont les points essentiels concernant les modalités évolutives des oreillons ?","a":"<div class=\"notion-course\"><p>Dans la <strong>majorité des cas</strong>, <span>les</span> oreillons évoluent vers une\n      <strong><span class=\"nc-green_bg\">guérison</span> <span class=\"nc-green_bg nc-bold\">spontanée</span> en <span>8 à 10 jours</span></strong>, en dehors de certaines complications.</p>\n      <table>\n        <thead><tr><th>Atteinte</th><th><span>Évolution</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Parotidite</strong></td><td><span class=\"nc-green_bg\">Guérison</span> <strong><span class=\"nc-green_bg nc-bold\">spontanée</span></strong> en <span>8-10 jours</span></td></tr>\n          <tr><td><strong><span>Orchite</span></strong></td><td><span>Évolution</span> favorable en <span>1 à 2 semaines</span></td></tr>\n          <tr><td><strong><span>Pancréatite</span></strong></td><td><strong><span class=\"nc-green nc-bold\">Guérison sans séquelle</span></strong></td></tr>\n          <tr><td><strong><span>Méningite</span></strong></td><td><strong><span class=\"nc-green nc-bold\">Guérison sans séquelle</span></strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège — complication locale.</strong> Au décours de la parotidite, des <strong><span><span class=\"nc-orange_bg\">foyers de nécrose</span></span></strong><span class=\"nc-orange_bg\">\n        peuvent apparaître</span> et faire le lit d'une <strong><span><span class=\"nc-red nc-bold\">parotidite chronique</span></span></strong>.\n      </div></div>"},{"i":"2f159b646e4a","n":165,"o":"165-6","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires en cas de suspicion d’oreillons","q":"Quels sont les points essentiels concernant les indications des examens complémentaires en cas de suspicion d’oreillons ?","a":"<div class=\"notion-course\"><p>Dans la <strong>forme typique</strong> (parotidite dans un <span>contexte évocateur</span>), le diagnostic est <strong>clinique</strong> :\n      <strong><span>aucun examen complémentaire n'est nécessaire</span></strong>.</p>\n      <p><span>Les</span> examens complémentaires ne sont indiqués que dans <strong>deux situations</strong> :</p>\n      <ul>\n        <li>En cas de <strong><span><span class=\"nc-purple_bg\">doute diagnostique</span></span></strong></li>\n        <li>En cas de <strong>complication</strong>, en particulier une <strong>localisation <span>extra-parotidienne</span> isolée</strong>\n        (<span>orchite</span>, <span>méningite</span> ou <span>pancréatite</span> sans parotidite associée)</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Devant une parotidite typique de l'enfant en contexte épidémique, on ne demande\n        <strong>rien</strong>. <span>Les</span> examens ne servent qu'à trancher un doute ou à documenter une forme <span>extra-parotidienne</span> isolée.\n      </div></div>"},{"i":"88d14fbc8cf5","n":165,"o":"165-7","u":"Examens complémentaires","t":"Connaître les modalités de confirmation des oreillons","q":"Quels sont les points essentiels concernant les modalités de confirmation des oreillons ?","a":"<div class=\"notion-course\"><ul><li>La confirmation virologique repose surtout sur RT-PCR d’un prélèvement salivaire/buccal précoce, selon protocole du laboratoire ; elle est utile devant doute, complication ou investigation de cas groupés.</li><li>Une PCR négative tardive n’exclut pas la maladie. Chez le vacciné, IgM peuvent manquer et IgG anciennes ne prouvent pas un épisode aigu ; interprétation sérologique avec contexte et laboratoire.</li><li>Biologie non spécifique selon complication : lipase si pancréatite suspectée, <span class=\"nc-red nc-bold\">LCS</span> si syndrome méningé et indication. Une hyperamylasémie peut être salivaire et ne suffit pas au diagnostic de pancréatite.</li></ul></div>"},{"i":"32547bc8a4d8","n":165,"o":"165-8","u":"Prise en charge","t":"Connaître les modalités thérapeutique des oreillons","q":"Quels sont les points essentiels concernant les modalités thérapeutique des oreillons ?","a":"<div class=\"notion-course\"><ul><li>Traitement symptomatique : hydratation, antalgiques adaptés, <span class=\"nc-green_bg\">repos</span> ; soutien scrotal si orchite. Une douleur testiculaire aiguë impose d’exclure une torsion.</li><li>Pas d’antiviral spécifique. Mesures d’hygiène respiratoire et limitation des contacts pendant la phase contagieuse ; éviter la collectivité en phase aiguë.</li><li>Distinguer l’absence d’éviction scolaire réglementaire systématique d’une absence de précautions. Informer et vérifier la vaccination de l’entourage ; en cas de cas groupés, suivre l’ARS.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d94181b28532f8f722c36d07?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
